INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65667253', 65667253, 'analyze_legacy', 'Kab. Kepulauan Meranti', 'kabkota', 'Dinas Perumahan Rakyat, Kawasan Permukiman, Pertanahan dan Lingkungan Hidup', 'Pembangunan/Peningkatan Semenisasi Halaman Masjid Babussalam Kelurahan Selatpanjang Timur', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Riau, Meranti (Kab.)', 127200000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Pembangunan/Peningkatan Semenisasi Halaman Masjid Babussalam Kelurahan Selatpanjang Timur;', 'Pekerjaan Konstruksi Fisik;', 127200000, 'high', 'Penggunaan anggaran daerah melalui perangkat urusan perumahan/permukiman untuk peningkatan halaman masjid terindikasi kurang selaras dengan fungsi belanja publik umum dan berisiko menjadi pembiayaan fasilitas institusi keagamaan tertentu. Dari judul item, manfaatnya tampak spesifik dan tidak jelas urgensi publiknya, sehingga patut dinilai sebagai pengadaan yang serius untuk dicermati.', NULL, NULL, 3, 1, 1, 1, 0, 2270038);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65667996', 65667996, 'analyze_legacy', 'Kementerian Perdagangan', 'central', 'BIRO UMUM DAN LAYANAN PENGADAAN', 'Belanja Pemeliharaan Gedung dan Bangunan - Pengelolaan Sarana Perkantoran', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 150000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '- Pemeliharaan Tanaman Halaman Gedung Kantor [1 PKT x 5 BLN] - Pemeliharaan Kolam Renang Pimpinan [1 PKT x 2 BLN] - Pemeliharaan Taman Vertikal - Pemeliharaan Area Lobi Pimpinan', '- Pemeliharaan Tanaman Halaman Gedung Kantor [1 PKT x 5 BLN] - Pemeliharaan Kolam Renang Pimpinan [1 PKT x 2 BLN] - Pemeliharaan Taman Vertikal - Pemeliharaan Area Lobi Pimpinan', 150000000, 'absurd', 'Terdapat komponen pemeliharaan kolam renang pimpinan dalam belanja pengelolaan sarana perkantoran. Fasilitas tersebut berindikasi kuat tidak esensial bagi fungsi layanan publik dan berisiko dipersepsikan sebagai penggunaan anggaran yang mewah/tidak patut. Dengan struktur paket yang mencampur kebutuhan umum dan fasilitas pimpinan, nilai paket layak dicermati sebagai potensi pemborosan signifikan.', NULL, NULL, 4, 1, 1, 1, 1, 2270039);
