INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65670067', 65670067, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultan Penyusunan Dokumen Analis Kebijakan Teknologi Pengelolaan Sampah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 177600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '10', '1. Identifikasi dan analisis gap kebijakan pengelolaan sampah di tingkat nasional dan daerah termasuk analisis dokumen perencanaan dan kebijakan nasional dan daerah; 2. Tinjauan ulang dan analisis gap lembaga pengelolaan persampahan, baik dari pemerintah dan non-pemerintah di daerah; 3. Analisis terkait data capaian, rekapitulasi infrastruktur terbangun, kebutuhan alokasi anggaran, rekapitulasi regulasi dan kebijakan sebagai pendukung analisis kebijakan pengelolaan sampah; dan 4. Pelaksanaaan dan pemberian input strategis dari sisi analisis kebijakan.', '1. Pendidikan minimal S1 bidang perencanaan dan kebijakan (planologi/perencanaan wilayah/kebijakan publik/lainnya sejenis); 2. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 4. Memiliki pengalaman kerja minimal 2 (dua) tahun dalam kegiatan/pekerjaan yang berkaitan dengan analisis kebijakan sektor persampahan/sanitasi/air minum (dibuktikan dengan referensi); 5. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 6. Memiliki kemampuan dalam melakukan review/telaah kebijakan dan/atau dokumen yang mendukung kebijakan di tingkat nasional maupun daerah; 7. Memiliki pengetahuan terkait sistem pengelolaan persampahan dan dapat melakukan pengolahan data pendukung yang terkait; 8. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; dan 9. Memiliki kemampuan dalam menyusun laporan, kajian, maupun dokumen secara sistematis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2271172);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65631545', 65631545, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KABUPATEN MAPPI', 'Belanja Barang Operasional Lainnya', 'Barang', 'E-Purchasing', 'Papua Selatan, Mappi (Kab.)', 52360000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pakaian Satpam ( 2, STEL, @ 1846759 ); 2. Pakaian Sopir/ Kebersihan/Pramubakti ( 24, STEL, @ 1420888 ); 3. Pakaian Dinas ( 4, STEL, @ 2500000 ); 4. Sewa Gedung Kantor ( 1, PKT, @ 4565000 );', 'Sesuai KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2271173);
