INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65669897', 65669897, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN JUNIOR ANALISA KAWASAN PERMUKIMAN KEGIATAN KOORDINASI PROGRAM TIGA JUTA RUMAH', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 195800009, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '10', '1. Melakukan telaah dan merumuskan rekomendasi serta strategi pengembangan kawasan permukiman dan penanganan permukiman kumuh dalam kerangka program tiga juta rumah. 2. Mengembangkan skema dan perangkat analisis kawasan permukiman, termasuk untuk isu permukiman kumuh. 3. Menganalisis dokumen penanganan permukiman kumuh terpadu yang disusun pemerintah daerah berdasarkan profil, data numerik, dan informasi spasial. 4. Melakukan koordinasi dan konsolidasi data serta kegiatan pembangunan (rolling pipeline project)/PSN perumahan yang berkaitan dengan pengembangan kawasan permukiman.', '1. Pendidikan minimal S1 dari jurusan perencanaan wilayah dan kota, atau sejenisnya; 2. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 6. Memiliki pengalaman dalam mengolah data baseline numerik dan spasial kumuh (dibuktikan dengan laporan); 7. Memiliki pengalaman dalam berkoordinasi/memfasilitasi pemerintah daerah dalam penyusunan program/kegiatan/rencana aksi permukiman, dimana menjadi nilai tambah jika terkait permukiman kumuh; 8. Memiliki pemahaman dasar mengenai isu permukiman kumuh dan penanganannya, termasuk konsep perencanaan terpadu, baseline numerik–spasial, serta pendekatan peningkatan kualitas permukiman (dibuktikan dengan referensi).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2271207);
