INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65669977', 65669977, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultan Penyusunan Dokumen Analisis Perumahan Perkotaan', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 186450000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '10', '1. Melakukan telaah dan merumuskan rekomendasi serta strategi terkait pengembangan perumahan perkotaan dalam kerangka program tiga juta rumah. 2. Melaksanakan analisis teknis perumahan perkotaan, termasuk rumah susun, kawasan berbasis TOD, dan bentuk pengembangan lainnya. 3. Melakukan koordinasi dan konsolidasi data serta kegiatan pembangunan (rolling pipeline project)/PSN perumahan yang berhubungan dengan perumahan perkotaan. 4. Melakukan analisis terhadap pelaksanaan dan progres kegiatan/program perumahan perkotaan guna menghasilkan insight substantif. 5. Memfasilitasi pemerintah daerah dalam penyusunan dokumen teknis pengembangan perumahan perkotaan. 6. Mengelola proses diskusi teknis, workshop, FGD, atau kegiatan lapangan untuk mendukung pengumpulan data serta pendalaman isu.', '1. Pendidikan minimal S1 dari jurusan perencanaan wilayah dan kota, ekonomi, dan sejenisnya, lulusan S2 (dibuktikan dengan ijasah); 2. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 6. Memiliki pengalaman kerja minimal 3 tahun terkait analisa dan penyusunan kebijakan perumahan dan permukiman (dibuktikan dengan kontrak/referensi); 7. Memiliki pengalaman dalam terkait pengembangan konsep kebijakan perumahan dan perkotaan, khususnya Kerjasama Pemerintah dan Badan Usaha (KPBU) dan Transit Oriented Development (TOD) (dibuktikan dengan referensi/kontrak); 8. Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah. 9. Memiliki pemahaman dasar terkait isu-isu pembangunan perkotaan terkini, termasuk regenerasi kawasan, penataan permukiman berkelanjutan, dan pengelolaan hunian perkotaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2272212);
